import java.util.*;

public class MinCostMaxFlow {
    static final int MAXN = 10000;
    static final int MAXM = 2000000;
    static final int INF = 0x3f3f3f3f;

    static int n, m, k, c, d;
    static class Edge {
        int to, next, cap, flow, cost;
        Edge(int to, int next, int cap, int flow, int cost) {
            this.to = to;
            this.next = next;
            this.cap = cap;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static Edge[] edge = new Edge[MAXM];
    static int[] head = new int[MAXN];
    static int tol;
    static int[] pre = new int[MAXN];
    static int[] dis = new int[MAXN];
    static boolean[] vis = new boolean[MAXN];
    static int N; // total nodes, numbered from 0 to N-1

    static void init(int n) {
        N = n;
        tol = 0;
        Arrays.fill(head, -1);
    }

    static void addedge(int u, int v, int cap, int cost) {
        edge[tol] = new Edge(v, head[u], cap, 0, cost);
        head[u] = tol++;
        edge[tol] = new Edge(u, head[v], 0, 0, -cost);
        head[v] = tol++;
    }

    static boolean spfa(int s, int t) {
        Arrays.fill(dis, INF);
        Arrays.fill(vis, false);
        Arrays.fill(pre, -1);
        dis[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        vis[s] = true;
        q.offer(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            vis[u] = false;
            for (int i = head[u]; i != -1; i = edge[i].next) {
                int v = edge[i].to;
                if (edge[i].cap > edge[i].flow && dis[v] > dis[u] + edge[i].cost) {
                    dis[v] = dis[u] + edge[i].cost;
                    pre[v] = i;
                    if (!vis[v]) {
                        vis[v] = true;
                        q.offer(v);
                    }
                }
            }
        }
        return pre[t] != -1;
    }

    static int minCostMaxflow(int s, int t, int[] cost) {
        int flow = 0;
        cost[0] = 0;
        while (spfa(s, t)) {
            int Min = INF;
            for (int i = pre[t]; i != -1; i = pre[edge[i ^ 1].to]) {
                if (Min > edge[i].cap - edge[i].flow)
                    Min = edge[i].cap - edge[i].flow;
            }
            for (int i = pre[t]; i != -1; i = pre[edge[i ^ 1].to]) {
                edge[i].flow += Min;
                edge[i ^ 1].flow -= Min;
                cost[0] += edge[i].cost * Min;
            }
            flow += Min;
        }
        return flow;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        init(MAXN);
        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            addedge(0, x, 1, 0);
        }
        for (int i = 0; i < 100; i++) {
            for (int j = 0; j < k; j++)
                addedge(1 + i * n, 9999, 1, i * c);
        }
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            for (int j = 1; j < 100; j++) {
                for (int gg = 1; gg <= k; gg++) {
                    addedge(u + (j - 1) * n, v + j * n, 1, (2 * gg - 1) * d);
                    addedge(v + (j - 1) * n, u + j * n, 1, (2 * gg - 1) * d);
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j < 100; j++) {
                addedge(i + (j - 1) * n, i + j * n, k, 0);
            }
        }

        int[] costArr = new int[1];
        minCostMaxflow(0, 9999, costArr);
        System.out.println(costArr[0]);
        sc.close();
    }
}
